const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length);
const q = Number(tok[0]);
function f(Nstr, K) {
  if (Nstr[0] === '-') return 0;
  const digs = Nstr.split('').map(Number), L = digs.length;
  const cnt = Array.from({ length: L }, () => new Array(K).fill(0));
  cnt[0][0] = 1;
  for (let r = 1; r < L; r++)
    for (let s = 0; s < K; s++)
      if (cnt[r - 1][s])
        for (let d = 0; d < 10; d++) cnt[r][(s + d) % K] += cnt[r - 1][s];
  let total = 0, pre = 0;
  for (let i = 0; i < L; i++) {
    const r = L - 1 - i;
    for (let d = 0; d < digs[i]; d++) total += cnt[r][(((-(pre + d)) % K) + K) % K];
    pre += digs[i];
  }
  if (pre % K === 0) total += 1;
  return total;
}
const out = [];
for (let i = 0; i < q; i++) {
  const a = tok[1 + 3 * i], b = tok[2 + 3 * i], k = Number(tok[3 + 3 * i]);
  const aMinus1 = (BigInt(a) - 1n).toString();
  out.push(f(b, k) - f(aMinus1, k));
}
console.log(out.join("\n"));

