#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll f(ll N, int K) {
    if (N < 0) return 0;
    string s = to_string(N);
    int L = s.size();
    vector<vector<ll>> cnt(L, vector<ll>(K, 0));
    cnt[0][0] = 1;
    for (int r = 1; r < L; r++)
        for (int t = 0; t < K; t++)
            if (cnt[r - 1][t])
                for (int d = 0; d < 10; d++) cnt[r][(t + d) % K] += cnt[r - 1][t];
    ll total = 0;
    int pre = 0;
    for (int i = 0; i < L; i++) {
        int dg = s[i] - '0', r = L - 1 - i;
        for (int d = 0; d < dg; d++) total += cnt[r][(((-(pre + d)) % K) + K) % K];
        pre += dg;
    }
    if (pre % K == 0) total++;
    return total;
}

int main() {
    int q;
    scanf("%d", &q);
    while (q--) {
        ll a, b;
        int k;
        scanf("%lld %lld %d", &a, &b, &k);
        printf("%lld\n", f(b, k) - f(a - 1, k));
    }
    return 0;
}
